#include <bits/stdc++.h>
using namespace std;
static long long d[2005][2005];
static int o[2005][2005];
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    while (cin >> n) {
        vector<long long> a(2 * n + 1);
        for (int i = 1, x; i <= n; ++i) {
            cin >> x;
            a[i] = a[i + n] = x;
        }
        for (int i = 1; i <= 2 * n; ++i) a[i] += a[i - 1], d[i][i] = 0, o[i][i] = i;
        for (int len = 2; len <= n; ++len)
            for (int l = 1, r = l + len - 1; r <= 2 * n; ++l, ++r) {
                d[l][r] = LLONG_MAX / 4;
                int R = min(r - 1, o[l + 1][r]);
                for (int k = o[l][r - 1]; k <= R; ++k) {
                    long long v = d[l][k] + d[k + 1][r] + a[r] - a[l - 1];
                    if (v < d[l][r]) d[l][r] = v, o[l][r] = k;
                }
            }
        long long ans = LLONG_MAX;
        for (int l = 1; l <= n; ++l) ans = min(ans, d[l][l + n - 1]);
        cout << ans << '\n';
    }
}
